<?php require_once __DIR__.'/../config/init.php';require_once __DIR__.'/../auth/verificar.php';$mov=$pdo->query("SELECT m.*,p.codigo,p.nome,u.nome usuario FROM movimentacoes_estoque m JOIN produtos p ON p.id=m.produto_id LEFT JOIN usuarios u ON u.id=m.usuario_id ORDER BY m.id DESC LIMIT 200")->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Movimentações</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><?php include __DIR__.'/../partials/menu.php';?><main class="main"><h1>Movimentações</h1><div class="panel"><table><thead><tr><th>Data</th><th>Produto</th><th>Tipo</th><th>Qtd.</th><th>Usuário</th><th>Observação</th></tr></thead><tbody><?php foreach($mov as $m):?><tr><td><?=date('d/m/Y H:i',strtotime($m['criado_em']))?></td><td><?=htmlspecialchars($m['codigo'].' - '.$m['nome'])?></td><td><span class="tag <?=$m['tipo']==='ENTRADA'?'green':'red'?>"><?=$m['tipo']?></span></td><td><?=number_format($m['quantidade'],2,',','.')?></td><td><?=htmlspecialchars($m['usuario']??'-')?></td><td><?=htmlspecialchars($m['observacao']??'')?></td></tr><?php endforeach;?></tbody></table></div></main></body></html>